+mod tests {
+    use super::*;
+    use crate::cl::MoveKind;
+    use crate::geometry::Point3;
+
+    fn feed(x: f64) -> Move {
+        Move::new(MoveKind::Feed, Point3::new(x, 0.0, -1.0), Point3::new(x + 1.0, 0.0, -1.0), Some(500.0))
+    }
+
+    #[test]
